def peacefulCircles(n, friendships, rivalries):
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    circles = n
    for a, b in friendships:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
            circles -= 1
    spoiled = set()
    for x, y in rivalries:
        rx = find(x)
        if rx == find(y):
            spoiled.add(rx)
    return circles - len(spoiled)
